// addBorders: the land borders added to Borders, never replacing what another region listed.
func addBorders(m map[string][]string) {
	for k, l := range m {
		cur, ok := Borders[k]
		if !ok {
			cur = []string{}
		}
		for _, n := range l {
			if !slices.Contains(cur, n) {
				cur = append(cur, n)
			}
		}
		Borders[k] = cur
	}
}

// InAsia: whether a city is in Asia (its own diseases, sims/sante.go; its own streets).
func InAsia(cityID string) bool {
	c, ok := FindCity(cityID)
	return ok && CountryOf(c).Land == "asie"
}

// AsiaCold: the Asian countries of real winters (the flu more than the fevers, sims/sante.go).
var AsiaCold = []string{"cn", "jp", "kr", "mn", "kz", "uz", "np", "bt"}

// AsiaTyphoid: where the typhoid still goes round (South Asia's great cities).
var AsiaTyphoid = []string{"in", "pk", "bd", "np"}

// AsieCountries: the ids of Asia's countries in the game (the update « pays-asie »).
var AsieCountries = []string{"cn", "jp", "in", "kr", "th", "vn", "id", "sg", "my", "ph", "hk", "tw", "pk", "bd", "lk", "np", "kh", "la", "mm", "mn", "kz", "uz", "mv", "bn", "bt"}

// AsieCommunes: every commune of Asia's cities (the update hides them while closed).
func AsieCommunes() []string {
	var out []string
	for _, c := range asie {
		for _, cm := range c.Communes {
			out = append(out, cm.ID)
		}
	}
	return out
}

// asieApprox: a real place where it's known to be (the geocoders didn't give it back: placed by hand, approximately).
func asieApprox(id, name, kind, quarter string, lat, lng float64, note string) Place {
	return approxAt(id, name, kind, quarter, lat, lng, note+" Position approchée.")
}

// asieHall: a real city hall placed approximately.
func asieHall(communeID, name, operator string, lat, lng float64, src string) Place {
	return Place{ID: "mairie-" + communeID, Name: name, Kind: "mairie", Lat: lat, Lng: lng, Real: true, Approx: true, Operator: operator, Source: game.Partial(name+" ; position approchée.", src, srcOSM)}
}

// withFaith: a place of worship's faith (game.FaithOf's: the temples, pagodas, shrines and gurdwaras are « autre »,
// one prays or visits there; the mosques keep the Friday prayer, the cathedrals the mass).
func withFaith(p Place, faith string) Place {
	p.Faith = faith
	return p
}

